mapper.select:
SELECT CL.*, CLC.* FROM CARE_LIST AS CL JOIN CARE_LIST_CATEGORY AS CLC ON CL.CL_CATEGORY_NO = CLC.CLC_NO WHERE CL.CL_IS_DELETED = 1 AND CLC.CLC_IS_DELETED = 1
AND CL.CL_CATEGORY_NO = #{infoNo}
AND CL.CL_USER_NO = #{u_no} ORDER BY CL.${sortValue} ${order} LIMIT #{start}, #{limit}

SELECT COUNT(*) FROM CARE_LIST AS CL JOIN CARE_LIST_CATEGORY AS CLC ON CL.CL_CATEGORY_NO = CLC.CLC_NO WHERE CL.CL_IS_DELETED = 1 AND CLC.CLC_IS_DELETED = 1
AND CL.CL_CATEGORY_NO = #{infoNo}
AND CL.CL_USER_NO = #{u_no}
